  "landing.hero.badge": "100% \u0a2e\u0a41\u0a2b\u0a3c\u0a24 \u0a05\u0a24\u0a47 \u0a17\u0a41\u0a2a\u0a24",
  "landing.hero.h1": "\u0a06\u0a2a\u0a23\u0a47 \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30 \u0a32\u0a08 \u0a38\u0a39\u0a40 \u0a38\u0a30\u0a15\u0a3e\u0a30\u0a40 \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a32\u0a71\u0a2d\u0a4b",
  "landing.hero.h1.accent": "\u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30",
  "landing.hero.sub": "VittVanni \u0a2d\u0a3e\u0a30\u0a24 \u0a26\u0a40\u0a06\u0a02 \u0a15\u0a47\u0a02\u0a26\u0a30\u0a40 \u0a05\u0a24\u0a47 \u0a30\u0a3e\u0a1c \u0a38\u0a30\u0a15\u0a3e\u0a30 \u0a26\u0a40\u0a06\u0a02 \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a28\u0a42\u0a70 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a40 \u0a2a\u0a4d\u0a30\u0a4b\u0a2b\u0a3e\u0a08\u0a32 \u0a28\u0a3e\u0a32 \u0a2e\u0a47\u0a32\u0a26\u0a3e \u0a39\u0a48 \u2014 \u0a38\u0a3e\u0a26\u0a40 \u0a2a\u0a70\u0a1c\u0a3e\u0a2c\u0a40, \u0a15\u0a26\u0a2e-\u0a26\u0a30-\u0a15\u0a26\u0a2e\u0964",
  "landing.hero.cta": "\u0a2e\u0a3f\u0a32\u0a3e\u0a09\u0a23\u0a3e \u0a38\u0a3c\u0a41\u0a30\u0a42 \u0a15\u0a30\u0a4b",
  "landing.hero.cta2": "\u0a07\u0a39 \u0a15\u0a3f\u0a35\u0a47\u0a02 \u0a15\u0a70\u0a2e \u0a15\u0a30\u0a26\u0a3e \u0a39\u0a48",
  "landing.how.title": "\u0a07\u0a39 \u0a15\u0a3f\u0a35\u0a47\u0a02 \u0a15\u0a70\u0a2e \u0a15\u0a30\u0a26\u0a3e \u0a39\u0a48",
  "landing.how.1.title": "\u0a06\u0a2a\u0a23\u0a47 \u0a2c\u0a3e\u0a30\u0a47 \u0a26\u0a71\u0a38\u0a4b",
  "landing.how.1.text": "\u0a06\u0a2a\u0a23\u0a47 \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30, \u0a38\u0a25\u0a3e\u0a28 \u0a05\u0a24\u0a47 \u0a2a\u0a3f\u0a1b\u0a4b\u0a15\u0a5c \u0a2c\u0a3e\u0a30\u0a47 9 \u0a38\u0a4c\u0a16\u0a47 \u0a38\u0a35\u0a3e\u0a32\u0a3e\u0a02 \u0a26\u0a47 \u0a1c\u0a35\u0a3e\u0a2c \u0a26\u0a3f\u0a13\u0964",
  "landing.how.2.title": "\u0a05\u0a38\u0a40\u0a02 \u0a24\u0a41\u0a39\u0a3e\u0a28\u0a42\u0a70 \u0a2e\u0a47\u0a32\u0a26\u0a47 \u0a39\u0a3e\u0a02",
  "landing.how.2.text": "\u0a38\u0a3e\u0a21\u0a40 \u0a2a\u0a4d\u0a30\u0a23\u0a3e\u0a32\u0a40 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 \u0a1c\u0a35\u0a3e\u0a2c\u0a3e\u0a02 \u0a24\u0a4b\u0a02 14 \u0a16\u0a47\u0a24\u0a30\u0a3e\u0a02 \u0a35\u0a3f\u0a71\u0a1a 90+ \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a28\u0a42\u0a70 \u0a26\u0a30\u0a1c\u0a3e \u0a26\u0a3f\u0a70\u0a26\u0a40 \u0a39\u0a48\u0964",
  "landing.how.3.title": "\u0a35\u0a3f\u0a06\u0a16\u0a3f\u0a06 \u0a2a\u0a3e\u0a13",
  "landing.how.3.text": "\u0a39\u0a30 \u0a38\u0a15\u0a40\u0a2e \u0a15\u0a3f\u0a09\u0a02 \u0a2b\u0a3f\u0a71\u0a1f \u0a2c\u0a48\u0a20\u0a26\u0a40 \u0a39\u0a48 \u0a07\u0a38 \u0a26\u0a47 \u0a38\u0a3e\u0a2b\u0a3c \u0a15\u0a3e\u0a30\u0a28 \u2014 \u0a2c\u0a3f\u0a28\u0a3e\u0a02 \u0a15\u0a3f\u0a38\u0a47 \u0a14\u0a16\u0a47 \u0a38\u0a3c\u0a2c\u0a26 \u0a26\u0a47\u0964",
  "landing.how.4.title": "\u0a2d\u0a30\u0a4b\u0a38\u0a47 \u0a28\u0a3e\u0a32 \u0a05\u0a30\u0a1c\u0a3c\u0a40 \u0a26\u0a3f\u0a13",
  "landing.how.4.text": "\u0a26\u0a38\u0a24\u0a3e\u0a35\u0a47\u0a1c\u0a3c, \u0a24\u0a3e\u0a30\u0a40\u0a16\u0a3c\u0a3e\u0a02 \u0a05\u0a24\u0a47 \u0a39\u0a2b\u0a3c\u0a24\u0a3e-\u0a26\u0a30-\u0a39\u0a2b\u0a3c\u0a24\u0a3e \u0a05\u0a30\u0a1c\u0a3c\u0a40 \u0a30\u0a4b\u0a21\u0a2e\u0a48\u0a2a \u0a2a\u0a3e\u0a13\u0964",
  "landing.stats.title": "\u0a05\u0a71\u0a17\u0a47 \u0a35\u0a27\u0a26\u0a47 \u0a09\u0a71\u0a26\u0a2e\u0a40\u0a06\u0a02 \u0a26\u0a3e \u0a2d\u0a30\u0a4b\u0a38\u0a3e",
  "landing.stats.schemes": "\u0a15\u0a35\u0a30 \u0a15\u0a40\u0a24\u0a40\u0a06\u0a02 \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02",
  "landing.stats.sectors": "\u0a35\u0a2a\u0a3e\u0a30\u0a15 \u0a16\u0a47\u0a24\u0a30",
  "landing.stats.states": "\u0a15\u0a35\u0a30 \u0a15\u0a40\u0a24\u0a47 \u0a30\u0a3e\u0a1c",
  "landing.stats.languages": "\u0a2d\u0a3e\u0a38\u0a3c\u0a3e\u0a35\u0a3e\u0a02",
  "landing.features.title": "\u0a05\u0a38\u0a32\u0a40 \u0a09\u0a71\u0a26\u0a2e\u0a40\u0a06\u0a02 \u0a32\u0a08 \u0a2c\u0a23\u0a3e\u0a07\u0a06 \u0a17\u0a3f\u0a06",
  "landing.features.1.title": "\u0a06\u0a35\u0a3e\u0a1c\u0a3c + \u0a1f\u0a48\u0a15\u0a38\u0a1f \u0a2a\u0a39\u0a3f\u0a32\u0a3e\u0a02",
  "landing.features.1.text": "\u0a15\u0a3f\u0a38\u0a47 \u0a35\u0a40 \u0a2b\u0a3c\u0a4b\u0a28 '\u0a24\u0a47 \u0a18\u0a71\u0a1f \u0a21\u0a3e\u0a1f\u0a3e \u0a35\u0a30\u0a24\u0a23 \u0a35\u0a3e\u0a32\u0a3e \u0a21\u0a3f\u0a1c\u0a3c\u0a3e\u0a08\u0a28\u0964",
  "landing.features.2.title": "23 \u0a2d\u0a3e\u0a38\u0a3c\u0a3e\u0a35\u0a3e\u0a02",
  "landing.features.2.text": "\u0a09\u0a71\u0a2a\u0a30 \u0a26\u0a47 \u0a2e\u0a40\u0a28\u0a42 \u0a24\u0a4b\u0a02 \u0a15\u0a4b\u0a08 \u0a35\u0a40 \u0a2d\u0a3e\u0a30\u0a24\u0a40 \u0a2d\u0a3e\u0a38\u0a3c\u0a3e \u0a1a\u0a41\u0a23\u0a4b\u0964",
  "landing.features.3.title": "\u0a06\u0a2b\u0a3c\u0a32\u0a3e\u0a08\u0a28 \u0a05\u0a28\u0a41\u0a15\u0a42\u0a32",
  "landing.features.3.text": "\u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a32\u0a4b\u0a15\u0a32 \u0a15\u0a48\u0a38\u0a3c \u0a39\u0a41\u0a70\u0a26\u0a40\u0a06\u0a02 \u0a39\u0a28 \u0a24\u0a3e\u0a02 \u0a1c\u0a4b \u0a2c\u0a3f\u0a28\u0a3e\u0a02 \u0a07\u0a70\u0a1f\u0a30\u0a28\u0a48\u0a71\u0a1f \u0a35\u0a40 \u0a1a\u0a71\u0a32 \u0a38\u0a15\u0a4b\u0964",
  "landing.features.4.title": "\u0a2a\u0a39\u0a3f\u0a32\u0a3e\u0a02 \u0a28\u0a3f\u0a71\u0a1c\u0a24\u0a3e",
  "landing.features.4.text": "\u0a24\u0a41\u0a39\u0a3e\u0a21\u0a3e \u0a21\u0a3e\u0a1f\u0a3e \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a3e \u0a39\u0a40 \u0a30\u0a39\u0a3f\u0a70\u0a26\u0a3e \u0a39\u0a48\u0964 \u0a15\u0a26\u0a47 \u0a35\u0a47\u0a1a\u0a3f\u0a06 \u0a28\u0a39\u0a40\u0a02 \u0a1c\u0a3e\u0a02\u0a26\u0a3e\u0964",
  "landing.cta.title": "\u0a06\u0a2a\u0a23\u0a40 \u0a38\u0a15\u0a40\u0a2e \u0a32\u0a71\u0a2d\u0a23 \u0a32\u0a08 \u0a24\u0a3f\u0a06\u0a30?",
  "landing.cta.text": "\u0a07\u0a38 \u0a35\u0a3f\u0a71\u0a1a 5 \u0a2e\u0a3f\u0a70\u0a1f \u0a24\u0a4b\u0a02 \u0a35\u0a40 \u0a18\u0a71\u0a1f \u0a32\u0a71\u0a17\u0a26\u0a3e \u0a39\u0a48\u0964",
  "auth.login.title": "\u0a1c\u0a40 \u0a06\u0a07\u0a06\u0a02 \u0a28\u0a42\u0a70",
  "auth.login.sub": "\u0a06\u0a2a\u0a23\u0a40 \u0a2e\u0a48\u0a1a\u0a3f\u0a70\u0a17 \u0a2f\u0a3e\u0a24\u0a30\u0a3e \u0a1c\u0a3e\u0a30\u0a40 \u0a30\u0a71\u0a16\u0a23 \u0a32\u0a08 \u0a32\u0a4c\u0a17 \u0a07\u0a28 \u0a15\u0a30\u0a4b",
  "auth.register.title": "\u0a06\u0a2a\u0a23\u0a3e \u0a16\u0a3e\u0a24\u0a3e \u0a2c\u0a23\u0a3e\u0a13",
  "auth.register.sub": "\u0a39\u0a2e\u0a47\u0a38\u0a3c\u0a3e \u0a2e\u0a41\u0a2b\u0a3c\u0a24\u0964 \u0a38\u0a15\u0a3f\u0a70\u0a1f\u0a3e\u0a02 \u0a35\u0a3f\u0a71\u0a1a \u0a30\u0a1c\u0a3f\u0a38\u0a1f\u0a30 \u0a15\u0a30\u0a4b\u0964",
  "auth.email": "\u0a08\u0a2e\u0a47\u0a32 \u0a2a\u0a24\u0a3e",
