  "auth.phone.invalid": "\u0a15\u0a3f\u0a30\u0a2a\u0a3e \u0a15\u0a30\u0a15\u0a47 10 \u0a05\u0a70\u0a15\u0a3e\u0a02 \u0a26\u0a3e \u0a38\u0a39\u0a40 \u0a2e\u0a4b\u0a2c\u0a3e\u0a08\u0a32 \u0a28\u0a70\u0a2c\u0a30 \u0a26\u0a3f\u0a13",
