  "auth.login.footer": "\u0a15\u0a40 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 \u0a15\u0a4b\u0a32 \u0a16\u0a3e\u0a24\u0a3e \u0a28\u0a39\u0a40\u0a02 \u0a39\u0a48?",
  "auth.register.footer": "\u0a15\u0a40 \u0a2a\u0a39\u0a3f\u0a32\u0a3e\u0a02 \u0a24\u0a4b\u0a02 \u0a16\u0a3e\u0a24\u0a3e \u0a39\u0a48?",
