  "questionnaire.auto.sub": "\u0a05\u0a38\u0a40\u0a02 \u0a07\u0a39 \u0a26\u0a41\u0a2c\u0a3e\u0a30\u0a3e \u0a28\u0a39\u0a40\u0a02 \u0a2a\u0a41\u0a71\u0a1b\u0a3e\u0a02\u0a17\u0a47 \u2014 \u0a07\u0a71\u0a25\u0a47 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 {sector} \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30 \u0a2c\u0a3e\u0a30\u0a47 \u0a15\u0a41\u0a1d \u0a1b\u0a4b\u0a1f\u0a47 \u0a38\u0a35\u0a3e\u0a32 \u0a39\u0a28\u0964",
