  "questionnaire.gate.title": "\u0a24\u0a41\u0a38\u0a40\u0a02 \u0a15\u0a3f\u0a35\u0a47\u0a02 \u0a38\u0a3c\u0a41\u0a30\u0a42 \u0a15\u0a30\u0a28\u0a3e \u0a1a\u0a3e\u0a39\u0a4b\u0a17\u0a47?",
  "questionnaire.gate.sub": "\u0a26\u0a4b\u0a35\u0a47\u0a02 \u0a24\u0a30\u0a40\u0a15\u0a3f\u0a06\u0a02 \u0a35\u0a3f\u0a71\u0a1a \u0a15\u0a41\u0a1d \u0a2e\u0a3f\u0a70\u0a1f \u0a32\u0a71\u0a17\u0a26\u0a47 \u0a39\u0a28\u0964 \u0a1c\u0a4b \u0a35\u0a40 \u0a24\u0a41\u0a39\u0a3e\u0a28\u0a42\u0a70 \u0a06\u0a38\u0a3e\u0a28 \u0a32\u0a71\u0a17\u0a47 \u0a1a\u0a41\u0a23\u0a4b\u0964",
  "questionnaire.gate.describeTitle": "\u0a2e\u0a48\u0a02 \u0a06\u0a2a\u0a23\u0a47 \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30 \u0a26\u0a3e \u0a35\u0a30\u0a23\u0a28 \u0a15\u0a30\u0a3e\u0a02\u0a17\u0a3e",
  "questionnaire.gate.describeSub": "\u0a06\u0a2a\u0a23\u0a47 \u0a15\u0a70\u0a2e \u0a2c\u0a3e\u0a30\u0a47 \u0a06\u0a2a\u0a23\u0a47 \u0a38\u0a3c\u0a2c\u0a26\u0a3e\u0a02 \u0a35\u0a3f\u0a71\u0a1a \u0a2c\u0a4b\u0a32\u0a4b \u0a1c\u0a3e\u0a02 \u0a32\u0a3f\u0a16\u0a4b\u0964 \u0a05\u0a38\u0a40\u0a02 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 \u0a32\u0a08 \u0a38\u0a2d \u0a2d\u0a30 \u0a26\u0a3f\u0a70\u0a26\u0a47 \u0a39\u0a3e\u0a02\u0964",
  "questionnaire.gate.formTitle": "\u0a15\u0a26\u0a2e-\u0a26\u0a30-\u0a15\u0a26\u0a2e \u0a2b\u0a3e\u0a30\u0a2e \u0a2d\u0a30\u0a4b",
  "questionnaire.gate.formSub": "\u0a1b\u0a4b\u0a1f\u0a47, \u0a38\u0a47\u0a27 \u0a35\u0a3e\u0a32\u0a47 \u0a38\u0a35\u0a3e\u0a32 \u2014 \u0a07\u0a71\u0a15 \u0a35\u0a3e\u0a30 \u0a35\u0a3f\u0a71\u0a1a \u0a07\u0a71\u0a15 \u0a38\u0a4c\u0a16\u0a3e \u0a38\u0a35\u0a3e\u0a32\u0964",
  "questionnaire.gate.noProfileNote": "\u0a35\u0a71\u0a16\u0a30\u0a40 \u0a2a\u0a4d\u0a30\u0a4b\u0a2b\u0a3e\u0a08\u0a32 \u0a2b\u0a3e\u0a30\u0a2e \u0a26\u0a40 \u0a32\u0a4b\u0a5c \u0a28\u0a39\u0a40\u0a02 \u2014 \u0a35\u0a30\u0a23\u0a28 \u0a15\u0a30\u0a4b \u0a05\u0a24\u0a47 \u0a05\u0a38\u0a40\u0a02 \u0a07\u0a38 \u0a28\u0a42\u0a70 \u0a2c\u0a23\u0a3e \u0a26\u0a3f\u0a70\u0a26\u0a47 \u0a39\u0a3e\u0a02\u0964",
  "questionnaire.describe.title": "\u0a06\u0a2a\u0a23\u0a47 \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30 \u0a2c\u0a3e\u0a30\u0a47 \u0a06\u0a2a\u0a23\u0a47 \u0a38\u0a3c\u0a2c\u0a26\u0a3e\u0a02 \u0a35\u0a3f\u0a71\u0a1a \u0a26\u0a71\u0a38\u0a4b",
  "questionnaire.describe.help": "\u0a26\u0a71\u0a38\u0a4b \u0a15\u0a3f \u0a24\u0a41\u0a38\u0a40\u0a02 \u0a15\u0a40 \u0a15\u0a30\u0a26\u0a47 \u0a39\u0a4b, \u0a07\u0a39 \u0a2a\u0a39\u0a3f\u0a32\u0a3e\u0a02 \u0a24\u0a4b\u0a02 \u0a1a\u0a71\u0a32 \u0a30\u0a3f\u0a39\u0a3e \u0a39\u0a48 \u0a1c\u0a3e\u0a02 \u0a38\u0a3c\u0a41\u0a30\u0a42 \u0a39\u0a4b \u0a30\u0a3f\u0a39\u0a3e \u0a39\u0a48, \u0a05\u0a24\u0a47 \u0a24\u0a41\u0a39\u0a3e\u0a28\u0a42\u0a70 \u0a15\u0a3f\u0a39\u0a5c\u0a40 \u0a2e\u0a26\u0a26 \u0a1a\u0a3e\u0a39\u0a40\u0a26\u0a40 \u0a39\u0a48 (\u0a15\u0a30\u0a1c\u0a3c\u0a3e, \u0a38\u0a3f\u0a16\u0a32\u0a3e\u0a08, \u0a35\u0a47\u0a1a\u0a23 \u0a35\u0a3f\u0a71\u0a1a \u0a38\u0a39\u0a3e\u0a07\u0a24\u0a3e \u0a06\u0a26\u0a3f)\u0964 \u0a24\u0a41\u0a38\u0a40\u0a02 \u0a2c\u0a4b\u0a32 \u0a35\u0a40 \u0a38\u0a15\u0a26\u0a47 \u0a39\u0a4b\u0964",
  "questionnaire.describe.mic": "\u0a2c\u0a4b\u0a32\u0a4b",
  "questionnaire.describe.micHint": "\u0a2c\u0a4b\u0a32\u0a23\u0a3e \u0a2a\u0a38\u0a70\u0a26 \u0a39\u0a48? \u0a2c\u0a1f\u0a28 \u0a26\u0a2c\u0a3e\u0a13 \u0a05\u0a24\u0a47 \u0a2c\u0a4b\u0a32\u0a4b:",
  "questionnaire.describe.micListening": "\u0a38\u0a41\u0a23 \u0a30\u0a3f\u0a39\u0a3e \u0a39\u0a3e\u0a02\u2026 \u0a2a\u0a42\u0a30\u0a3e \u0a39\u0a4b\u0a23 '\u0a24\u0a47 \u0a38\u0a1f\u0a3e\u0a2a \u0a26\u0a2c\u0a3e\u0a13",
  "questionnaire.describe.analyze": "\u0a2e\u0a47\u0a30\u0a47 \u0a15\u0a3e\u0a30\u0a4b\u0a2c\u0a3e\u0a30 \u0a28\u0a42\u0a70 \u0a38\u0a2e\u0a1d\u0a4b",
  "questionnaire.describe.thinking": "\u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 \u0a38\u0a3c\u0a2c\u0a26 \u0a2a\u0a5c\u0a4d\u0a39 \u0a05\u0a24\u0a47 \u0a38\u0a2e\u0a1d \u0a30\u0a3f\u0a39\u0a3e \u0a39\u0a3e\u0a02\u2026",
  "questionnaire.describe.failed": "\u0a2e\u0a3e\u0a2b\u0a3c \u0a15\u0a30\u0a28\u0a3e, \u0a39\u0a41\u0a23 \u0a2e\u0a48\u0a02 \u0a07\u0a38 \u0a28\u0a42\u0a70 \u0a38\u0a2e\u0a1d \u0a28\u0a39\u0a40\u0a02 \u0a38\u0a15\u0a3f\u0a06\u0964 \u0a15\u0a3f\u0a30\u0a2a\u0a3e \u0a15\u0a30\u0a15\u0a47 \u0a26\u0a41\u0a2c\u0a3e\u0a30\u0a3e \u0a15\u0a4b\u0a38\u0a3c\u0a3f\u0a38\u0a3c \u0a15\u0a30\u0a4b\u0964",
  "questionnaire.describe.summaryTitle": "\u0a2e\u0a48\u0a02 \u0a24\u0a41\u0a39\u0a3e\u0a21\u0a47 \u0a2c\u0a3e\u0a30\u0a47 \u0a07\u0a39 \u0a38\u0a2e\u0a1d\u0a3f\u0a06",
  "questionnaire.describe.edit": "\u0a2e\u0a47\u0a30\u0a47 \u0a38\u0a3c\u0a2c\u0a26 \u0a2c\u0a26\u0a32\u0a4b",
  "questionnaire.describe.pickCategory": "\u0a24\u0a41\u0a38\u0a40\u0a02 \u0a15\u0a3f\u0a38 \u0a35\u0a30\u0a17 \u0a28\u0a3e\u0a32 \u0a38\u0a2c\u0a70\u0a27\u0a24 \u0a39\u0a4b?",
  "questionnaire.describe.pickState": "\u0a24\u0a41\u0a38\u0a40\u0a02 \u0a15\u0a3f\u0a38 \u0a30\u0a3e\u0a1c \u0a35\u0a3f\u0a71\u0a1a \u0a15\u0a70\u0a2e \u0a15\u0a30\u0a26\u0a47 \u0a39\u0a4b?",
  "questionnaire.describe.apply": "\u0a07\u0a39 \u0a38\u0a39\u0a40 \u0a39\u0a48 \u2014 \u0a2e\u0a47\u0a30\u0a40\u0a06\u0a02 \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a32\u0a3f\u0a06\u0a13",
  "questionnaire.describe.applying": "\u0a24\u0a41\u0a39\u0a3e\u0a21\u0a40 \u0a2a\u0a4d\u0a30\u0a4b\u0a2b\u0a3e\u0a08\u0a32 \u0a05\u0a24\u0a47 \u0a38\u0a15\u0a40\u0a2e\u0a3e\u0a02 \u0a2c\u0a23\u0a3e\u0a08\u0a06\u0a02 \u0a1c\u0a3e \u0a30\u0a39\u0a40\u0a06\u0a02 \u0a39\u0a28\u2026",
  "questionnaire.describe.need.capital": "\u0a15\u0a30\u0a1c\u0a3c\u0a3e / \u0a2a\u0a42\u0a70\u0a1c\u0a40",
  "questionnaire.describe.need.subsidy": "\u0a38\u0a2c\u0a38\u0a3f\u0a21\u0a40 / \u0a17\u0a4d\u0a30\u0a3e\u0a02\u0a1f",
  "questionnaire.describe.need.training": "\u0a38\u0a3f\u0a16\u0a32\u0a3e\u0a08",
  "questionnaire.describe.need.marketing": "\u0a2e\u0a3e\u0a30\u0a15\u0a40\u0a1f\u0a3f\u0a70\u0a17 \u0a2e\u0a26\u0a26",
  "questionnaire.describe.need.legal": "\u0a30\u0a1c\u0a3f\u0a38\u0a1f\u0a4d\u0a30\u0a47\u0a38\u0a3c\u0a28 \u0a2e\u0a26\u0a26",
  "questionnaire.describe.need.tech": "\u0a2e\u0a38\u0a3c\u0a40\u0a28 / \u0a24\u0a15\u0a28\u0a3e\u0a32\u0a4b\u0a1c\u0a40",
